mapper.sql:
SELECT
p.materialCode,
p.materialVersion,
p.customerCode,
p.dDFactoryFlag,
p.barCodeStr,
p.labelNumber,
p.manufactureDate,
p.labelPrintDateTime,
s.scanDate,
s.scanMachine,
s.scanIPAddress,
s.duplicateFlag
FROM (
    SELECT
    materialCode,
    materialVersion,
    customerCode,
    dDFactoryFlag,
    barCodeStr,
    labelNumber,
    manufactureDate,
    labelPrintDateTime
    FROM dbo.vwBYDLabelPrint_Select


            AND materialCode = #{materialCode}


            AND materialVersion = #{materialVersion}


            AND customerCode = #{customerCode}


            AND dDFactoryFlag = #{dDFactoryFlag}


            AND barCodeStr LIKE CONCAT('%', #{barCodeStr}, '%')


            AND labelNumber = #{labelNumber}


            AND manufactureDate >= #{labelStartTime}


            AND manufactureDate <= DATEADD(DAY, 1, #{labelEndTime})


            AND labelPrintDateTime >= #{printStartTime}


            AND labelPrintDateTime <= DATEADD(DAY, 1, #{printEndTime})

         and labelNumber >= #{labelNumberStart}
         and labelNumber <= #{labelNumberEnd}

) p
INNER JOIN dbo.vwBYDLabelScan_Select s
    ON p.materialCode = s.materialCode AND p.barCodeStr = s.barCodeStr

        AND s.scanDate >= #{startTime}


        AND s.scanDate <= DATEADD(DAY, 1, #{endTime})


        AND s.scanMachine = #{scanMachine}


        AND s.scanIPAddress = #{scanIPAddress}


        AND s.duplicateFlag = #{duplicateFlag}

mapper.select:


     and materialCode = #{materialCode}
     and materialVersion = #{materialVersion}
     and customerCode = #{customerCode}
     and dDFactoryFlag = #{dDFactoryFlag}
     and barCodeStr like concat('%', #{barCodeStr}, '%')
     and labelNumber = #{labelNumber}
     and manufactureDate >= #{labelStartTime}
     and manufactureDate <= DATEADD(day, 1, #{labelEndTime})
     and labelPrintDateTime >= #{printStartTime}
     and labelPrintDateTime <= DATEADD(day, 1, #{printEndTime})
     and labelNumber >= #{labelNumberStart}
     and labelNumber <= #{labelNumberEnd}

order by labelPrintDateTime desc

SELECT COUNT(barCodeStr)
FROM dbo.vwBYDLabelPrint_Select
WHERE materialCode = #{materialCode}
 and manufactureDate >= #{labelStartTime}
 and manufactureDate < DATEADD(day, 1, #{labelEndTime})


 and labelNumber = #{labelNumber}
 and labelNumber >= #{labelNumberStart}
 and labelNumber <= #{labelNumberEnd}

SELECT p.materialCode, p.materialVersion, p.customerCode, p.dDFactoryFlag, p.barCodeStr, p.labelNumber, p.manufactureDate, p.labelPrintDateTime
FROM dbo.vwBYDLabelPrint_Select p
WHERE p.materialCode = #{materialCode}
AND p.labelPrintDateTime >= #{labelStartTime}
AND p.labelPrintDateTime < DATEADD(day, 1, #{labelEndTime}) 
 and p.labelNumber = #{labelNumber}
 and p.labelNumber >= #{labelNumberStart}
 and p.labelNumber <= #{labelNumberEnd}
AND NOT EXISTS (
SELECT 1
FROM dbo.vwBYDLabelScan_Select s
WHERE s.materialCode = p.materialCode
AND s.barCodeStr = p.barCodeStr
);
